package com.wolinski.shop.orders.api;

import com.wolinski.shop.money.Money;
import java.time.Instant;

public interface OrderFacade {

    String place(String customerId, Money total, Instant placedAt);

    void confirm(String orderId);

    void cancel(String orderId);

    OrderSummary summary(String orderId);
}

package com.wolinski.shop.orders.internal;

import com.wolinski.shop.money.Money;
import com.wolinski.shop.orders.api.OrderFacade;
import com.wolinski.shop.orders.api.OrderSummary;
import java.time.Instant;
import java.util.UUID;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class OrderService implements OrderFacade {

    private final OrderRepository orders;

    public OrderService(OrderRepository orders) {
        this.orders = orders;
    }

    @Override
    @Transactional
    public String place(String customerId, Money total, Instant placedAt) {
        Order order = new Order(UUID.randomUUID().toString(), customerId, total, placedAt);
        orders.save(order);
        return order.id();
    }

    @Override
    @Transactional
    public void confirm(String orderId) {
        orders.get(orderId).changeStatus("CONFIRMED");
    }

    @Override
    @Transactional
    public void cancel(String orderId) {
        orders.get(orderId).changeStatus("CANCELLED");
    }

    @Override
    @Transactional(readOnly = true)
    public OrderSummary summary(String orderId) {
        Order order = orders.get(orderId);
        return new OrderSummary(order.id(), order.customerId(), order.total(), order.status());
    }
}

package com.wolinski.shop.orders.internal;

import com.wolinski.shop.money.Money;
import java.time.Instant;

public class Order {

    private final String id;
    private final String customerId;
    private final Instant placedAt;
    private Money total;
    private String status = "PLACED";

    public Order(String id, String customerId, Money total, Instant placedAt) {
        this.id = id;
        this.customerId = customerId;
        this.total = total;
        this.placedAt = placedAt;
    }

    public String id() {
        return id;
    }

    public String customerId() {
        return customerId;
    }

    public Instant placedAt() {
        return placedAt;
    }

    public Money total() {
        return total;
    }

    public void changeTotal(Money total) {
        this.total = total;
    }

    public String status() {
        return status;
    }

    public void changeStatus(String status) {
        this.status = status;
    }
}

package com.wolinski.shop.orders.internal;

import java.util.Collection;
import java.util.Map;
import java.util.NoSuchElementException;
import java.util.concurrent.ConcurrentHashMap;
import org.springframework.stereotype.Repository;

@Repository
public class OrderRepository {

    private final Map<String, Order> orders = new ConcurrentHashMap<>();

    public void save(Order order) {
        orders.put(order.id(), order);
    }

    public Order get(String orderId) {
        Order order = orders.get(orderId);
        if (null == order) {
            throw new NoSuchElementException(orderId);
        }
        return order;
    }

    public Collection<Order> all() {
        return orders.values();
    }
}

package com.wolinski.shop;

import com.wolinski.shop.platform.InMemoryTransactionManager;
import java.time.Clock;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.ComponentScan;
import org.springframework.context.annotation.Configuration;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.annotation.EnableTransactionManagement;

@Configuration
@ComponentScan
@EnableTransactionManagement
public class ShopConfig {

    @Bean
    Clock clock() {
        return Clock.systemUTC();
    }

    @Bean
    PlatformTransactionManager transactionManager() {
        return new InMemoryTransactionManager();
    }
}

package com.wolinski.shop.orders.internal;

import com.wolinski.shop.money.Money;
import com.wolinski.shop.payments.internal.Payment;
import com.wolinski.shop.payments.internal.PaymentRepository;
import java.time.LocalDate;
import java.time.ZoneOffset;
import org.springframework.stereotype.Component;

/** The nightly report for accounting. */
@Component
public class OrderReports {

    private final OrderRepository orders;
    private final PaymentRepository payments;

    public OrderReports(OrderRepository orders, PaymentRepository payments) {
        this.orders = orders;
        this.payments = payments;
    }

    public long placedToday() {
        LocalDate today = LocalDate.now(ZoneOffset.UTC);
        return orders.all().stream()
                .filter(order -> order.placedAt().atZone(ZoneOffset.UTC).toLocalDate().equals(today))
                .count();
    }

    public long placedYesterday() {
        LocalDate yesterday = LocalDate.now().minusDays(1);
        return orders.all().stream()
                .filter(order -> order.placedAt().atZone(ZoneOffset.UTC).toLocalDate().equals(yesterday))
                .count();
    }

    public Money capturedRevenue() {
        Money sum = Money.pln(0);
        for (Order order : orders.all()) {
            for (Payment payment : payments.findByOrderId(order.id())) {
                sum = sum.plus(payment.amount());
            }
        }
        return sum;
    }
}

package com.wolinski.shop.orders.internal;

import com.wolinski.shop.customers.api.CustomerFacade;
import com.wolinski.shop.notifications.api.Notifier;
import com.wolinski.shop.shipping.api.CarrierGateway;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;

/** A customer sends an order back. */
@Component
public class OrderReturns {

    private final OrderRepository orders;
    private final CarrierGateway carrier;
    private final Notifier notifier;
    private final CustomerFacade customers;

    public OrderReturns(OrderRepository orders, CarrierGateway carrier, Notifier notifier, CustomerFacade customers) {
        this.orders = orders;
        this.carrier = carrier;
        this.notifier = notifier;
        this.customers = customers;
    }

    @Transactional
    public String startReturn(String orderId) {
        Order order = orders.get(orderId);
        order.changeStatus("RETURNING");
        String label = carrier.book("return-" + orderId);
        notifier.send(customers.emailOf(order.customerId()), "Return " + orderId, "Your return label: " + label);
        return label;
    }
}

