import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.money.Money;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import org.junit.jupiter.api.Test;

class OrderServiceExpireStaleTest {

    private static final Instant NOW = Instant.parse("2026-10-31T12:00:00Z");

    private final OrderRepository orders = new OrderRepository();
    private final OrderService service = new OrderService(orders, Clock.fixed(NOW, ZoneOffset.UTC));

    @Test
    void cancelsPlacedOrdersOlderThan30Days() {
        orders.save(new Order("old", "c-1", Money.pln(100), NOW.minusSeconds(31L * 24 * 3600)));

        assertEquals(1, service.expireStale());
        assertEquals("CANCELLED", orders.get("old").status());
    }

    @Test
    void keepsOrdersPlacedExactly30DaysAgoOrLater() {
        orders.save(new Order("edge", "c-1", Money.pln(100), NOW.minusSeconds(30L * 24 * 3600)));
        orders.save(new Order("recent", "c-1", Money.pln(100), NOW.minusSeconds(3600)));

        assertEquals(0, service.expireStale());
        assertEquals("PLACED", orders.get("edge").status());
        assertEquals("PLACED", orders.get("recent").status());
    }

    @Test
    void leavesOldOrdersInOtherStatusesAlone() {
        Order confirmed = new Order("confirmed", "c-1", Money.pln(100), NOW.minusSeconds(40L * 24 * 3600));
        confirmed.changeStatus("CONFIRMED");
        orders.save(confirmed);
        orders.save(new Order("cancelled", "c-1", Money.pln(100), NOW.minusSeconds(40L * 24 * 3600)));
        orders.get("cancelled").changeStatus("CANCELLED");

        assertEquals(0, service.expireStale());
        assertEquals("CONFIRMED", orders.get("confirmed").status());
    }

    @Test
    void returnsCountOfCancelledOrders() {
        orders.save(new Order("a", "c-1", Money.pln(100), NOW.minusSeconds(45L * 24 * 3600)));
        orders.save(new Order("b", "c-1", Money.pln(100), NOW.minusSeconds(60L * 24 * 3600)));
        orders.save(new Order("c", "c-1", Money.pln(100), NOW.minusSeconds(3600)));

        assertEquals(2, service.expireStale());
        assertEquals(0, service.expireStale());
    }
}
}
